// Intervalo esperado (min). Un job se considera atrasado si supera 2x ese intervalo.
const EXPECTED = { nvd: 360, ct_log: 1440, tls_expiry: 1440, shodan: 1440,
                   scorecard_refresh_all: 60, cleanup_archive: 1440 };
const jobs = $input.all().map(i => i.json).filter(j => j.job_type);
const byType = Object.fromEntries(jobs.map(j => [j.job_type, j]));
const now = Date.now();
const problems = [];
const staleExecutions = Number(jobs[0]?.stale_executions || 0);
if (staleExecutions > 0) {
  problems.push({ name: 'workflow_executions', issue: staleExecutions + ' ejecución(es) manual(es) marcada(s) como fallida(s) por ausencia de callback durante ' + Number($env.WORKFLOW_STALE_HOURS || 12) + ' horas' });
}
for (const [type, exp] of Object.entries(EXPECTED)) {
  const j = byType[type];
  if (!j || !j.last_run) { problems.push({ name: type, issue: 'nunca se ha ejecutado' }); continue; }
  const age = Math.round((now - new Date(j.last_run).getTime()) / 60000);
  if (age > exp * 2) problems.push({ name: type, issue: 'atrasado ' + age + ' min (esperado cada ' + exp + ')' });
  else if (j.status === 'error' || j.status === 'partial') problems.push({ name: type, issue: 'última ejecución incompleta o con errores' });
}
const h = $('Backend Health').first().json || {};
const backendOk = h.statusCode >= 200 && h.statusCode < 300;
if (!backendOk) problems.unshift({ name: 'backend', issue: 'health check falló (' + (h.statusCode || h.error || 'sin respuesta') + ')' });
return [{ json: {
  healthy: problems.length === 0,
  backend_down: !backendOk,
  problems,
  fingerprint: 'n8n_health:' + problems.map(p => p.name).sort().join(',')
}}];

const manual = $('Manual Trigger');
if (!manual.isExecuted) return [];
const trigger = manual.first().json || {};
const request = trigger.body || trigger;
if (!request.request_id) return [];
const result = $('Detect Problems').first().json || {};
const problems = Array.isArray(result.problems) ? result.problems : [];
const status = result.backend_down ? 'failed' : problems.length ? 'partial' : 'success';
return [{ json: {
  request_id: request.request_id,
  workflow_code: 'wf-08',
  status,
  summary: problems.length ? 'Health check detectó ' + problems.length + ' problema(s).' : 'Health check sin incidencias.',
  details: { healthy: Boolean(result.healthy), backend_down: Boolean(result.backend_down), problems }
} }];
